export function popoverPosition(anchor,panel,viewport,options={}){
const gap=Math.max(0,options.offset??8);
const padding=Math.max(0,options.padding??12);
const left=viewport.left+padding,top=viewport.top+padding;
const right=viewport.left+viewport.width-padding,bottom=viewport.top+viewport.height-padding;
const maxWidth=Math.max(0,right-left),maxHeight=Math.max(0,bottom-top);
const width=Math.min(panel.width,maxWidth),height=Math.min(panel.height,maxHeight);
const room={top:anchor.top-top-gap,bottom:bottom-anchor.top-anchor.height-gap,
left:anchor.left-left-gap,right:right-anchor.left-anchor.width-gap};
let side=options.side??'bottom';
const opposite={top:'bottom',bottom:'top',left:'right',right:'left'};
const required=side==='top'||side==='bottom'?height:width;
if(room[side]<required&&room[opposite[side]]>room[side])
side=opposite[side];
const vertical=side==='top'||side==='bottom';
let align=options.align??'start';
if(vertical&&options.rtl&&align!=='center')
align=align==='start'?'end':'start';
const across=(start,size,panelSize)=>start+(align==='center'?(size-panelSize)/2:align==='end'?size-panelSize:0);
const x=vertical?across(anchor.left,anchor.width,width):side==='left'?anchor.left-width-gap:anchor.left+anchor.width+gap;
const y=vertical?side==='top'?anchor.top-height-gap:anchor.top+anchor.height+gap:across(anchor.top,anchor.height,height);
return{x:Math.max(left,Math.min(x,right-width)),y:Math.max(top,Math.min(y,bottom-height)),side,maxWidth,maxHeight};
}
